/**
 * @file v92_modulus_encoder.h
 * @brief Declaration of V92ModulusEncoder, the V.92 modulus encoder of the transmitter.
 *
 * The encoder turns the data bits of one symbol group into twelve digits of a mixed-radix number, with a fix-up for a number larger than 63 bits.
 * The definition is in v92_modulus_encoder.cpp.  The object (0x54 bytes) is embedded in V92Transmitter; its i386 layout is checked by the
 * assertions in v92_modulus_encoder_layout.inc (generated by tools/layout_gen.py from layouts/vpcm/v92_modulus_encoder.layout).
 *
 * The object holds the product of the twelve radices (prod_), two derived 64-bit constants (a_, b_) that reset() computes from the radices with a
 * shift search, the radices themselves (m_[12], copied from V92MappingParams::m_), the number of data bits (nbits_ = V92MappingParams::w0_), a
 * carry flag between calls (flag_) and the mode (mode_: 0 = encode, 1 / 2 = write the largest digit values of two digit patterns; reset() sets 0,
 * V92Transmitter sets 1 / 2 directly).
 *
 * 64-bit arithmetic: every product is the low 64 bits (wrapping, unsigned arithmetic); the divisions and remainders are signed (truncating toward
 * zero); the divisor is a 32-bit radix zero-extended, and a zero radix traps (division by zero).
 */
#ifndef V92_MODULUS_ENCODER_H
#define V92_MODULUS_ENCODER_H

#include "core/dsp_cxx.h"
#include "v92_cp.h" /* V92MappingParams */

/* The i386 ABI aligns a 64-bit integer to 4; these types keep that layout (sizeof 0x54, embedded at 4-byte alignment in V92Transmitter) on x86-64 too. */
typedef uint64_t u64_a4 __attribute__((aligned(4)));
typedef int64_t i64_a4 __attribute__((aligned(4)));

/** @brief Mixed-radix modulus encoder of the V.92 transmitter (data bits of one group -> twelve digits). */
class V92ModulusEncoder
{
public:
  /** @brief Clear nbits_ and the twelve radices.  prod_, a_, b_, flag_ and mode_ are left untouched until reset(). */
  V92ModulusEncoder();

  /**
   * @brief Load the radices and the bit count and derive prod_, a_ and b_.
   * @param p  mapping parameters: w0_ (number of data bits) and m_[12] (radices)
   * @note  Also clears flag_ and sets mode_ to 0 (encode).
   */
  void reset(V92MappingParams* p);

  /**
   * @brief Encode one group of data bits.
   * @param bits    nbits_ bytes, the LSB of each byte is one data bit (bit 0 first)
   * @param digits  receives twelve digits (mode 0: mixed-radix digits of the number; mode 1 / 2: the largest digit values of a pattern)
   */
  void progress(unsigned char* bits, unsigned* digits);

public:
  u64_a4 prod_;    ///< product of the twelve radices (mod 2^64)
  i64_a4 a_;       ///< set by reset(): (Q1 * (Q2 >> k)) >> (62 - k), or 0
  u64_a4 b_;       ///< set by reset(): (Q1 * (Q2 >> k')) << k' & 0x7fff...f, or the full product
  uint32_t m_[12]; ///< the radices
  uint32_t nbits_; ///< number of data bits
  uint32_t flag_;  ///< complement flag (progress() toggles it)
  uint32_t mode_;  ///< 0 = encode, 1 / 2 = largest digit patterns
};

typedef V92ModulusEncoder P15_V92ModulusEncoder;

#include "v92_modulus_encoder_layout.inc"

#endif /* V92_MODULUS_ENCODER_H */
